"""Dump bundle contents for inspection."""
import sys
sys.path.insert(0, "/tmp/gitlib")
from bundle import parse_bundle


def fmt_tree(payload):
    entries = []
    pos = 0
    while pos < len(payload):
        sp = payload.index(b" ", pos)
        mode = payload[pos:sp].decode()
        nul = payload.index(b"\0", sp)
        name = payload[sp + 1:nul].decode()
        oid = payload[nul + 1:nul + 21].hex()
        entries.append((mode, name, oid))
        pos = nul + 21
    return entries


for path in ["/app/bundle1.bundle", "/app/bundle2.bundle"]:
    print(f"===== {path} =====")
    refs, prereqs, objects = parse_bundle(path)
    for oid, obj in objects.items():
        if obj.type == "commit":
            print(f"--- commit {oid} ---")
            print(obj.payload.decode())
        elif obj.type == "tree":
            print(f"--- tree {oid} ---")
            for mode, name, eoid in fmt_tree(obj.payload):
                print(f"  {mode} {name} {eoid}")
    for oid, obj in objects.items():
        if obj.type == "blob":
            print(f"--- blob {oid} ({len(obj.payload)} bytes) ---")
            try:
                print(obj.payload.decode())
            except UnicodeDecodeError:
                print("<binary>")
            print()

