"""Analyze examples.json to infer the mapping rule."""
import json

with open("/app/examples.json") as f:
    examples = json.load(f)

for idx, ex in enumerate(examples):
    inp = ex["input"]
    out = ex["output"]
    print(f"=== example {idx}: input {len(inp)}x{len(inp[0])}, output {len(out)}x{len(out[0])} ===")
    print("input:")
    for row in inp:
        print("  ", row)
    print("output:")
    for row in out:
        print("  ", row)

    # Hypothesis: output[i][j] = d[(i+j) % 3] where d learned from nonzero input cells keyed by (i+j)%3
    d = {}
    ok = True
    for i, row in enumerate(inp):
        for j, v in enumerate(row):
            if v != 0:
                key = (i + j) % 3
                if key in d and d[key] != v:
                    print(f"  INCONSISTENT key {key}: {d[key]} vs {v} at ({i},{j})")
                    ok = False
                d[key] = v
    print("  learned dict (key=(i+j)%3):", d)
    # check coverage
    missing = [k for k in range(3) if k not in d]
    if missing:
        print("  MISSING keys:", missing)
        ok = False
    # verify output
    match = True
    for i, row in enumerate(out):
        for j, v in enumerate(row):
            expect = d.get((i + j) % 3)
            if v != expect:
                print(f"  MISMATCH at ({i},{j}): output={v}, expect={expect}")
                match = False
    print("  output matches hypothesis:", match, "| input consistent:", ok)

